.robot-switch { display: flex; gap: 4px; padding: 4px; background: #111719; border: 1px solid #293231; border-radius: 7px; button { display: flex; align-items: center; justify-content: center; gap: 7px; flex: 1; font-size: 11px; padding: 8px 0; color: #82908a; background: transparent; border-radius: 4px; .icon { width: 15px; height: 15px; } &.selected { background: #303c2b; color: var(--accent); } } }
.robot-info { display: flex; justify-content: space-between; align-items: center; margin-top: 18px; > div { display: flex; gap: 10px; align-items: center; } strong { font-size: 14px; font-weight: 500; letter-spacing: .3px; } small { display: block; font-size: 9px; margin-top: 5px; color: var(--muted); } }.device-symbol { display: grid; place-items: center; width: 36px; height: 36px; background: #272f2b; border-radius: 7px; color: #9cafa0; .icon { width: 22px; height: 22px; } }.sim-chip { color: #889c7b; font-size: 8px; border: 1px solid #3c4c32; padding: 3px 5px; border-radius: 3px; letter-spacing: .5px; }
.robot-specs { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 18px 0; padding-bottom: 17px; border-bottom: 1px solid var(--border); > span { display: flex; align-items: center; gap: 9px; font-size: 9px; color: var(--muted); &:last-child { border-left: 1px solid var(--border); padding-left: 13px; } b { font-size: 12px; font-weight: 400; color: #cbd5cf; small { color: #6b7a70; font-size: 8px; } } } }
.section-label { display: flex; justify-content: space-between; align-items: center; font-size: 11px; color: #acb5af; margin-bottom: 12px; > span { color: #607368; font-size: 8px; letter-spacing: 1px; } }
.action-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; button { display: flex; align-items: center; justify-content: center; gap: 9px; height: 37px; font-size: 11px; background: #202729; border: 1px solid #333d3a; border-radius: 6px; color: #a6b3ab; position: relative; .icon { width: 16px; height: 16px; } &:hover:not(:disabled) { border-color: #839765; } &.active { color: var(--accent); background: #2c3625; border-color: #5d7141; }.dot { position: absolute; right: 8px; width: 3px; height: 3px; } } }
.speed-control { margin-top: 21px; .section-label { margin-bottom: 13px; }.speed-value { color: var(--text); font-size: 15px; letter-spacing: 0; small { color: var(--muted); font-size: 9px; } } }
.range-labels { display: flex; justify-content: space-between; font-size: 8px; color: #6d7a72; margin-top: 9px; }
