.playback-controls { border-top: 1px solid var(--border); margin-top: 18px; padding-top: 16px; .rate-value { color: var(--cyan); font-size: 13px; letter-spacing: 0; } }
.loop-row { display: flex; align-items: center; justify-content: space-between; margin-top: 16px; gap: 10px; font-size: 10px; color: var(--muted); label { display: flex; align-items: center; gap: 4px; } input { accent-color: var(--accent); } .btn { min-height: 32px; padding: 6px 8px; font-size: 10px; .icon { width: 12px; height: 12px; } } }
.record-controls { border-top: 1px solid var(--border); padding-top: 16px; margin-top: 16px; }.record-buttons { display: flex; gap: 5px; .btn { padding: 7px 5px; min-height: 32px; font-size: 10px; flex: 1; } .recording { color: var(--danger); border-color: var(--danger); } }.record-note { font-size: 9px; color: var(--faint); margin-top: 10px; line-height: 1.7; }.replay-progress { color: var(--success); font-size: 10px; margin-top: 12px; }
.control-footer { border-top: 1px solid var(--border); padding: 15px 0 12px; p { display: flex; align-items: center; justify-content: center; gap: 5px; font-size: 8px; color: #66766c; margin-top: 12px; .icon { width: 11px; height: 11px; } } }.emergency-button { width: 100%; font-size: 11px; justify-content: flex-start; min-height: 35px; padding: 8px 10px; .icon { width: 14px; height: 14px; } span { margin-left: auto; font-size: 7px; letter-spacing: .7px; opacity: .65; } }
@media(min-width:701px) and (max-height:850px) { .control-panel { padding-top: 14px; }.control-title { margin-bottom: 10px; }.robot-info { margin-top: 10px; }.robot-specs { margin-block: 10px; padding-bottom: 10px; }.control-tabs { margin-bottom: 10px; }.control-footer { padding-block: 10px 8px; p { margin-top: 8px; } } }
@media(max-width:700px) { .control-panel { height: auto; }.control-body { max-height: 560px; }.action-grid button,.control-tabs button,.record-buttons .btn,.loop-row .btn { min-height: 44px; } }
</style>
